 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v != 0}
    objs = []
    for c in colors:
        cells = [(r, x) for r in range(h) for x in range(w) if grid[r][x] == c]
        objs.append((c, cells, min(r for r, x in cells)))
    top = min(y for c, cells, y in objs)
    out = [[0] * w for _ in range(h)]
    for c, cells, y in objs:
        dy = top - y
        for r, x in cells:
            rr = r + dy
            if 0 <= rr < h:
                out[rr][x] = c
    return out
