 "content": "def transform(grid):
    """Translate each color's pattern vertically so every pattern's top row
    aligns with the top row of the color-8 reference pattern."""
    h, w = len(grid), len(grid[0])
    colors = {value for row in grid for value in row if value != 0}
    cells_by_color = {
        color: [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        for color in colors
    }
    target_top = min(r for r, c in cells_by_color[8])
    out = [[0] * w for _ in range(h)]
    for color, cells in cells_by_color.items():
        shift = target_top - min(r for r, c in cells)
        for r, c in cells:
            rr = r + shift
            if 0 <= rr < h:
                out[rr][c] = color
    return out
"
